PREFIX : <https://w3id.org/rastro/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (COUNT(DISTINCT ?d) AS ?n) WHERE {
  {
    SELECT DISTINCT ?d WHERE {
      ?b rdfs:label "Breast Neoplasms"@en .
      ?cb :within ?b .
      ?t1 :condition ?cb ; :phase ?p1 ; :testsDrug ?d .
      FILTER(?p1 IN ("PHASE3", "PHASE2/PHASE3"))
    }
  }
  {
    SELECT DISTINCT ?d WHERE {
      ?l rdfs:label "Lung Neoplasms"@en .
      ?cl :within ?l .
      ?t2 :condition ?cl ; :phase ?p2 ; :testsDrug ?d .
      FILTER(?p2 IN ("PHASE3", "PHASE2/PHASE3"))
    }
  }
  ?d :approved true .
}
